import React, { useEffect, useRef, useState } from 'react';

export default function BrideGroomSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVisible(true);
    }, { threshold: 0.2 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section ref={ref} style={{
      background: 'linear-gradient(180deg, #fce8f5 0%, #fdf0f8 100%)',
      padding: '20px 20px 80px',
      textAlign: 'center',
    }}>
      <style>{`
        @keyframes slideLeft {
          from { opacity: 0; transform: translateX(-50px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes slideRight {
          from { opacity: 0; transform: translateX(50px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.8); }
          to { opacity: 1; transform: scale(1); }
        }
        .sl { opacity: 0; }
        .sr { opacity: 0; }
        .sc { opacity: 0; }
        .sl.vis { animation: slideLeft 0.8s ease 0.2s forwards; }
        .sr.vis { animation: slideRight 0.8s ease 0.4s forwards; }
        .sc.vis { animation: scaleIn 0.6s ease 0.1s forwards; }
        .couple-full-photo {
          width: 340px;
          height: 260px;
          border-radius: 50%;
          overflow: hidden;
          margin: 0 auto 50px;
          background: linear-gradient(135deg, #ffd6e8, #f8c0d8);
          box-shadow: 0 10px 40px rgba(233,30,140,0.2);
          border: 4px solid #f8d0e8;
        }
      `}</style>

      {/* Couple photo (full, same as opening) */}
      <div className={`sc${visible ? ' vis' : ''}`}>
        <div className="couple-full-photo">
          <CoupleSVGFull />
        </div>
      </div>

      {/* Groom & Bride names */}
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        gap: '20px',
        flexWrap: 'wrap',
        maxWidth: '900px',
        margin: '0 auto',
      }}>
        {/* Groom */}
        <div className={`sl${visible ? ' vis' : ''}`} style={{ flex: 1, minWidth: '260px', textAlign: 'center' }}>
          <h2 style={{
            fontFamily: "'Dancing Script', cursive",
            fontSize: 'clamp(1.8rem, 5vw, 2.5rem)',
            color: '#333',
            marginBottom: '16px',
          }}>
            Nobita Nobi
          </h2>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '1rem',
            color: '#666',
            marginBottom: '6px',
          }}>
            Putra dari:
          </p>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '0.95rem',
            color: '#555',
            fontWeight: 500,
          }}>
            Nobisuke Nobi &amp; Tamako Nobi
          </p>
        </div>

        {/* Ampersand */}
        <div style={{
          fontFamily: "'Dancing Script', cursive",
          fontSize: '2.5rem',
          color: '#e91e8c',
          padding: '0 10px',
        }}>&amp;</div>

        {/* Bride */}
        <div className={`sr${visible ? ' vis' : ''}`} style={{ flex: 1, minWidth: '260px', textAlign: 'center' }}>
          <h2 style={{
            fontFamily: "'Dancing Script', cursive",
            fontSize: 'clamp(1.8rem, 5vw, 2.5rem)',
            color: '#333',
            marginBottom: '16px',
          }}>
            Shizuka Minamoto
          </h2>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '1rem',
            color: '#666',
            marginBottom: '6px',
          }}>
            Putri dari:
          </p>
          <p style={{
            fontFamily: "'Poppins', sans-serif",
            fontSize: '0.95rem',
            color: '#555',
            fontWeight: 500,
          }}>
            Yoshio Minamoto &amp; Michiko Minamoto
          </p>
        </div>
      </div>
    </section>
  );
}

function CoupleSVGFull() {
  return (
    <svg viewBox="0 0 340 260" width="340" height="260">
      <defs>
        <radialGradient id="bgGrad3" cx="50%" cy="40%" r="60%">
          <stop offset="0%" stopColor="#fffde8" />
          <stop offset="100%" stopColor="#ffd6e8" />
        </radialGradient>
      </defs>
      <rect width="340" height="260" fill="url(#bgGrad3)" />
      <ellipse cx="60" cy="60" rx="80" ry="60" fill="#b8e0a0" opacity="0.6" />
      <ellipse cx="280" cy="60" rx="80" ry="60" fill="#b8e0a0" opacity="0.6" />
      <ellipse cx="170" cy="30" rx="100" ry="50" fill="#c8f0a0" opacity="0.5" />
      {[20, 310].map((x, i) => (
        <g key={i}>
          <circle cx={x} cy="190" r="14" fill="#ff6b9d" opacity="0.8" />
          <circle cx={x} cy="190" r="8" fill="#ff4080" opacity="0.9" />
          <circle cx={x - 8} cy="185" r="6" fill="#ff8ab8" opacity="0.7" />
          <circle cx={x + 8} cy="185" r="6" fill="#ff8ab8" opacity="0.7" />
