      {/* Groom */}
      <rect x="88" y="165" width="74" height="90" rx="12" fill="#2d3a5c" />
      <polygon points="125,165 140,185 110,185" fill="white" />
      <polygon points="125,170 130,195 120,195" fill="#e91e8c" />
      <ellipse cx="125" cy="120" rx="38" ry="42" fill="#ffd5a8" />
      <ellipse cx="125" cy="85" rx="36" ry="22" fill="#2d2016" />
      <ellipse cx="95" cy="100" rx="14" ry="18" fill="#2d2016" />
      <ellipse cx="155" cy="100" rx="14" ry="18" fill="#2d2016" />
      <circle cx="112" cy="122" r="14" fill="none" stroke="#555" strokeWidth="3" />
      <circle cx="138" cy="122" r="14" fill="none" stroke="#555" strokeWidth="3" />
      <line x1="126" y1="122" x2="124" y2="122" stroke="#555" strokeWidth="2" />
      <circle cx="112" cy="122" r="8" fill="white" />
      <circle cx="138" cy="122" r="8" fill="white" />
      <circle cx="113" cy="123" r="5" fill="#3d2a1a" />
      <circle cx="139" cy="123" r="5" fill="#3d2a1a" />
      <circle cx="115" cy="121" r="2" fill="white" />
