      <ellipse cx="125" cy="133" rx="4" ry="3" fill="#e8b888" />
      <path d="M115,142 Q125,150 135,142" fill="none" stroke="#c8806a" strokeWidth="2" strokeLinecap="round" />
      <ellipse cx="88" cy="122" rx="7" ry="10" fill="#ffd5a8" />
      <ellipse cx="162" cy="122" rx="7" ry="10" fill="#ffd5a8" />
      <circle cx="105" cy="175" r="6" fill="#ffb8d0" />
      <circle cx="105" cy="175" r="3" fill="#ff8ab0" />
      {/* Bride */}
      <path d="M178,165 Q195,155 215,155 Q235,155 252,165 L262,255 L168,255 Z" fill="white" />
      <path d="M185,180 Q215,170 245,180" fill="none" stroke="#f0d0e8" strokeWidth="2" />
      <path d="M182,195 Q215,185 248,195" fill="none" stroke="#f0d0e8" strokeWidth="2" />
      <ellipse cx="215" cy="115" rx="36" ry="40" fill="#ffd5a8" />
      <ellipse cx="215" cy="82" rx="34" ry="20" fill="#1a1008" />
      <ellipse cx="183" cy="100" rx="13" ry="22" fill="#1a1008" />
      <ellipse cx="247" cy="100" rx="13" ry="22" fill="#1a1008" />
      <path d="M193,80 L198,70 L205,78 L215,65 L225,78 L232,70 L237,80" fill="none" stroke="#ffd700" strokeWidth="3" />
      <ellipse cx="204" cy="117" rx="9" ry="10" fill="white" />
      <ellipse cx="226" cy="117" rx="9" ry="10" fill="white" />
      <circle cx="205" cy="118" r="6" fill="#1a0e0a" />
      <circle cx="227" cy="118" r="6" fill="#1a0e0a" />
      <circle cx="207" cy="116" r="2" fill="white" />
      <circle cx="229" cy="116" r="2" fill="white" />
      <path d="M196,110 Q200,106 208,109" fill="none" stroke="#1a0e0a" strokeWidth="1.5" />
      <path d="M218,109 Q224,106 232,110" fill="none" stroke="#1a0e0a" strokeWidth="1.5" />
      <ellipse cx="195" cy="128" rx="10" ry="5" fill="#ffb8c8" opacity="0.5" />
      <ellipse cx="235" cy="128" rx="10" ry="5" fill="#ffb8c8" opacity="0.5" />
      <ellipse cx="215" cy="128" rx="3" ry="2" fill="#e8b888" />
      <path d="M206,138 Q215,146 224,138" fill="none" stroke="#c8806a" strokeWidth="2" strokeLinecap="round" />
      <ellipse cx="180" cy="116" rx="7" ry="10" fill="#ffd5a8" />
      <ellipse cx="250" cy="116" rx="7" ry="10" fill="#ffd5a8" />
      <circle cx="180" cy="127" r="4" fill="#ffd700" />
      <circle cx="250" cy="127" r="4" fill="#ffd700" />
      <path d="M200,158 Q215,165 230,158" fill="none" stroke="#ffd700" strokeWidth="2" />
      <path d="M157,130 C157,126 162,122 165,126 C168,122 173,126 173,130 C173,136 165,142 165,142 C165,142 157,136 157,130Z" fill="#e91e8c" opacity="0.8" />
      <ellipse cx="170" cy="258" rx="140" ry="20" fill="#a8e090" opacity="0.4" />
    </svg>
  );
}
